/** pcaSql - selectPrjGoal - 과제목표 조회 */
SELECT
     VESTICODE           as "vEstiCode"         /* 평가코드              */
   , VPROJECTGOAL        as "vProjectGoal"      /* 과제목표              */
   , VPROJECTMILESTONE   as "vProjectMileStone" /* 평가 기간내 Milestone */
FROM 
   TCA4003

       VPROJECTCODE = #{vProjectCode}
   AND VESTICODE = #{vEstiCode}

mapper.update:
/** pcaSql - updateProjectGoal - 과제목표 저장 */
UPDATE TCA4003

    VPROJECTGOAL      = #{vProjectGoal}     , 
    VPROJECTMILESTONE = #{vProjectMilestone}, 


       VESTICODE = #{vEstiCode}
   AND VPROJECTCODE = #{vProejctCode}

mapper.select:
/** pcaSql - selectContributionList - 기여도 데이터 조회 */ SELECT A.VESTICODE as "vEstiCode" /* 평가연도 */ , A.VPROJECTCODE as "vProjectCode" /* 과제코드 */ , A.VEMPLNO as "vEmplNo" /* 사번 */ , B.VNAME as "vName" /* 성명 */ , B.VDEPTNAME as "vDeptName" /* 부서명 */ , B.VTEAMNAME as "vTeamName" /* 팀명 */ , B.VPOSNAME as "vPosName" /* 직위명 */ , A.VWORK as "vWork" /* 업무 */ , A.NCONTRIBUTION as "nContribution" /* 기여율 */ , A.VCONTENT as "vContent" /* 평가의견 */ , A.VFINISH as "vFinish" /* 완료여부 */ , A.VCONFIRM as "vConfirm" /* 확연여부 */ FROM TCA4005 A, TCA4002 B
A.VESTICODE = B.VESTICODE AND A.VEMPLNO = B.VEMPLNO AND A.VESTICODE = #{vEstiCode} AND A.VPROJECTCODE = #{vProjectCode} AND B.VESTIYN = 'Y'
ORDER BY B.VNAME

mapper.delete:
/** pcaSql - updateBoardFile - PDF 변환 여부 수정 */
UPDATE TWR4004

    VPDFFILENAME   = #{vPdfFileName}   , 
    VPDFCREATEDATE = TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS') , 


   AND VWEEK = #{vWeek}
   AND VEMPLNO = #{vEmplNo}
   AND VWORKTYPE = '1'
   AND NSEQNO = #{nSeqNo}
   AND NFILESEQNO = #{nFileSeqNo}

mapper.select:
/** pcaSql - selectAdditionalEmplNoList - 추가할 참여 연구원 조회 */ SELECT VESTICODE as "vEstiCode" /* 평가코드 */ , VEMPLNO as "vEmplNo" /* 사번 */ , VNAME as "vName" /* 성명 */ , VDEPTNAME as "vDeptName" /* 센터명 */ , VTEAMNAME as "vTeamName" /* 팀명 */ , VPOSNAME as "vPosName" /* 직위명 */ FROM ( SELECT VESTICODE , VEMPLNO , VNAME , VDEPTNAME , VTEAMNAME , VPOSNAME FROM TCA4002
VESTICODE = #{vEstiCode} AND VESTIYN = 'Y' AND VEMPLNO NOT IN ( SELECT VEMPLNO FROM TCA4005
VESTICODE = #{vEstiCode} AND VPROJECTCODE = #{vProjectCode}
)
)
VNAME LIKE '%' || #{vName} || '%'
AND VDEPTNAME LIKE #{vDeptName} || '%'
ORDER BY VNAME

mapper.insert:
/** pcaSql - insertEstiEmplNo - 참여연구원 추가 */
INSERT INTO
   TCA4005
   (
        VESTICODE
      , VPROJECTCODE
      , VEMPLNO
      , NCONTRIBUTION
      , VFINISH
   )
VALUES
   (
        #{vEstiCode}
      , #{vProjectCode}
      , #{vEmplNo}
      , 0
      , 'Y'
   )

mapper.delete:
/** pcaSql - deleteEstiEmplNo - 참여연구원 삭제 */
DELETE FROM TCA4005

       VESTICODE = #{vEstiCode}
   AND VPROJECTCODE = #{vProjectCode}
   AND VEMPLNO = #{vEmplNo}

mapper.update:
/** pcaSql - updateContribution - 연구원 기여도 저장 */
UPDATE
   TCA4005

    NCONTRIBUTION = #{nContribution}, 
    VCONTENT      = #{vContent}     , 


       VESTICODE = #{vEstiCode}
   AND VPROJECTCODE = #{vProjectCode}
   AND VEMPLNO = #{vEmplNo}

/** pcaSql - updateEstiStep2 - 기여도 입력완료 처리 */
UPDATE
   TCA4003
SET
   VESTISTEP = '2'

       VESTICODE = #{vEstiCode}
   AND VPROJECTCODE = #{vProjectCode}
   AND VPROJECTPM = #{vProjectPm}

/** pcaSql - updateEstiStep2CheckRetire - 기여도 입력완료 퇴직자 확인 처리 */
MERGE INTO TCA4005 A
USING (
    SELECT VESTICODE, VEMPLNO, VRETIREYN
      FROM TCA4002
     WHERE VESTICODE = #{vEstiCode}
       AND VRETIREYN = 'Y'
) B
ON (A.VESTICODE = B.VESTICODE AND A.VEMPLNO = B.VEMPLNO)
WHEN MATCHED THEN
  UPDATE SET A.VCONFIRM = B.VRETIREYN
   WHERE A.VPROJECTCODE = #{vProjectCode}

mapper.select:
/** pcaSql - selectReview - 기여도 검토 의견(평가의견) 조회 */ SELECT VREVIEWCONTENT as "vReviewContent" /* 기여율 검토 의견 */ FROM ( SELECT VESTICODE , VPROJECTCODE , NSEQNO , VREVIEWCONTENT FROM TCA4006
VESTICODE = #{vEstiCode} AND VPROJECTCODE = #{vProjectCode}
ORDER BY NSEQNO DESC )
ROWNUM = 1

