mapper.select:
/** pcaSql - selectEstiEmplNoList - 평가대상자 조회 */ SELECT VESTICODE as "vEstiCode" /* 평가연도 */ , VEMPLNO as "vEmplNo " /* 사번 */ , VNAME as "vName " /* 성명 */ , VDEPTNAME as "vDeptName" /* 센터명 */ , VTEAMNAME as "vTeamName" /* 팀명 */ , VPOSNAME as "vPosName " /* 직위명 */ FROM TCA4002
VESTICODE = #{vEstiCode} AND VESTIYN = 'Y'
ORDER BY NAME
